const DFS_DIRECT_READ_STATUS_METADATA_KEY: &str = "sinomo.dfs.direct-read.status";
const DFS_DIRECT_READ_STATUS_FOUND: &str = "found";
const DFS_DIRECT_READ_STATUS_NOT_FOUND: &str = "not-found";
const DFS_DIRECT_READ_STATUS_REJECTED: &str = "rejected";
const DFS_DIRECT_READ_REQUEST_ID_METADATA_KEY: &str = "sinomo.dfs.direct-read.request-id";
const DFS_DIRECT_READ_OBJECT_ID_METADATA_KEY: &str = "sinomo.dfs.direct-read.object-id";
const DFS_DIRECT_READ_VERSION_METADATA_KEY: &str = "sinomo.dfs.direct-read.version";
const DFS_DIRECT_READ_CONTENT_HASH_METADATA_KEY: &str = "sinomo.dfs.direct-read.content-hash";
const DFS_DIRECT_READ_CONTENT_SIZE_METADATA_KEY: &str = "sinomo.dfs.direct-read.content-size";
const DFS_DIRECT_READ_REJECTION_METADATA_KEY: &str = "sinomo.dfs.direct-read.rejection";
pub const DFS_DIRECT_READ_STREAM_CHUNK_BYTES: usize = 4 * 1024 * 1024;

#[derive(Debug)]
pub struct DfsDirectReadStreamResponse {
    pub response: ObjectRpcResponse,
    pub reader: Option<BlobReader>,
}

pub fn dfs_direct_read_rpc_request(
    request: &DfsDirectReadRequest,
) -> Result<ObjectRpcRequest, NetworkError> {
    let mut rpc_request =
        ObjectRpcRequest::encode_body(DFS_DIRECT_READ_ROUTE, DFS_RPC_CATEGORY, request)?;
    sinomo_network::set_object_rpc_request_stream_mode(
        &mut rpc_request,
        sinomo_network::ObjectRpcRequestStreamMode::RawStreamedDaemonResponse,
    );
    Ok(rpc_request)
}

pub fn dfs_direct_read_rpc_request_accepts_streamed_response(request: &ObjectRpcRequest) -> bool {
    request.route == DFS_DIRECT_READ_ROUTE
        && sinomo_network::object_rpc_request_stream_mode(request).expects_raw_streamed_response()
}

#[cfg(test)]
pub(crate) fn dfs_direct_read_rpc_request_from_message_command(
    command: &DfsMessageCommand,
) -> Result<Option<ObjectRpcRequest>, NetworkError> {
    let DfsNetworkMessage::ReadRequest(request) = &command.routed_message.message else {
        return Ok(None);
    };
    let Some(request) = dfs_direct_read_request_from_read_request(request) else {
        return Ok(None);
    };
    dfs_direct_read_rpc_request(&request).map(Some)
}

fn dfs_direct_read_request_from_read_request(
    request: &DfsReadRequest,
) -> Option<DfsDirectReadRequest> {
    let content_size_bytes = request.content_size_bytes?;
    if !direct_full_read_response_allowed(request, content_size_bytes) {
        return None;
    }
    Some(DfsDirectReadRequest {
        request_id: request.request_id.clone(),
        object_id: request.object_id.clone(),
        version: request.version.clone()?,
        content_hash: request.content_hash.clone()?,
        content_size_bytes,
    })
}

pub fn handle_dfs_direct_read_rpc_request(
    data_dir: &SinomoDataDir,
    request: ObjectRpcRequest,
) -> Result<ObjectRpcResponse, DfsError> {
    if request.route != DFS_DIRECT_READ_ROUTE {
        return Err(DfsError::Network {
            message: format!("unknown DFS direct read route {}", request.route),
        });
    }
    let request: DfsDirectReadRequest = request.decode_body().map_err(DfsError::from_network)?;
    let response = serve_dfs_direct_read_request(data_dir, request)?;
    dfs_direct_read_rpc_response(response).map_err(DfsError::from_network)
}

pub fn handle_dfs_direct_read_stream_rpc_request(
    data_dir: &SinomoDataDir,
    request: ObjectRpcRequest,
) -> Result<DfsDirectReadStreamResponse, DfsError> {
    if request.route != DFS_DIRECT_READ_ROUTE {
        return Err(DfsError::Network {
            message: format!("unknown DFS direct read route {}", request.route),
        });
    }
    let request: DfsDirectReadRequest = request.decode_body().map_err(DfsError::from_network)?;
    serve_dfs_direct_read_stream_request(data_dir, request)
}

fn serve_dfs_direct_read_request(
    data_dir: &SinomoDataDir,
    request: DfsDirectReadRequest,
) -> Result<DfsReadResponse, DfsError> {
    data_dir
        .ensure_root_layout()
        .map_err(|source| DfsError::Metadata {
            message: source.to_string(),
        })?;
    let object_id = request.object_id.clone();
    let result = if request.content_size_bytes > DFS_DIRECT_REMOTE_READ_MAX_BYTES {
        DfsReadResult::Rejected {
            reason: format!(
                "DFS direct read {} is {} bytes, above direct response limit {}",
                request.object_id, request.content_size_bytes, DFS_DIRECT_REMOTE_READ_MAX_BYTES
            ),
        }
    } else {
        let content = LocalContentStore::new(data_dir.dfs_dir().join("content"))?;
        match read_blob_for_direct_read_rpc_response(
            &content,
            &request.content_hash,
            request.content_size_bytes,
        )? {
            Some(bytes) => DfsReadResult::Found(DfsReadData {
                object_id: request.object_id,
                version: request.version,
                content_hash: Some(request.content_hash),
                bytes,
            }),
            None => DfsReadResult::NotFound,
        }
    };
    Ok(DfsReadResponse {
        request_id: request.request_id,
        object_id,
        result,
    })
}

fn serve_dfs_direct_read_stream_request(
    data_dir: &SinomoDataDir,
    request: DfsDirectReadRequest,
) -> Result<DfsDirectReadStreamResponse, DfsError> {
    data_dir
        .ensure_root_layout()
        .map_err(|source| DfsError::Metadata {
            message: source.to_string(),
        })?;
    if request.content_size_bytes > DFS_DIRECT_REMOTE_READ_MAX_BYTES {
        let response = DfsReadResponse {
            request_id: request.request_id,
            object_id: request.object_id.clone(),
            result: DfsReadResult::Rejected {
                reason: format!(
                    "DFS direct read {} is {} bytes, above direct response limit {}",
                    request.object_id, request.content_size_bytes, DFS_DIRECT_REMOTE_READ_MAX_BYTES
                ),
            },
        };
        return Ok(DfsDirectReadStreamResponse {
            response: dfs_direct_read_rpc_response(response).map_err(DfsError::from_network)?,
            reader: None,
        });
    }
    let content = LocalContentStore::new(data_dir.dfs_dir().join("content"))?;
    let reader = match content.open_blob_stream(&request.content_hash) {
        Ok(reader) => reader,
        Err(_) => {
            let response = DfsReadResponse {
                request_id: request.request_id,
                object_id: request.object_id,
                result: DfsReadResult::NotFound,
            };
            return Ok(DfsDirectReadStreamResponse {
                response: dfs_direct_read_rpc_response(response).map_err(DfsError::from_network)?,
                reader: None,
            });
        }
    };
    if reader.size_bytes() != request.content_size_bytes {
        let response = DfsReadResponse {
            request_id: request.request_id,
            object_id: request.object_id,
            result: DfsReadResult::NotFound,
        };
        return Ok(DfsDirectReadStreamResponse {
            response: dfs_direct_read_rpc_response(response).map_err(DfsError::from_network)?,
            reader: None,
        });
    }
    let mut response = ObjectRpcResponse::from_encoded_body(DFS_DIRECT_READ_ROUTE, Vec::new());
    response.metadata.insert(
        DFS_DIRECT_READ_STATUS_METADATA_KEY.to_string(),
        DFS_DIRECT_READ_STATUS_FOUND.to_string(),
    );
    response.metadata.insert(
        DFS_DIRECT_READ_REQUEST_ID_METADATA_KEY.to_string(),
        request.request_id,
    );
    response.metadata.insert(
        DFS_DIRECT_READ_OBJECT_ID_METADATA_KEY.to_string(),
        request.object_id.to_string(),
    );
    response.metadata.insert(
        DFS_DIRECT_READ_VERSION_METADATA_KEY.to_string(),
        request.version.to_string(),
    );
    response.metadata.insert(
        DFS_DIRECT_READ_CONTENT_HASH_METADATA_KEY.to_string(),
        request.content_hash,
    );
    response.metadata.insert(
        DFS_DIRECT_READ_CONTENT_SIZE_METADATA_KEY.to_string(),
        request.content_size_bytes.to_string(),
    );
    sinomo_network::set_object_rpc_response_stream_mode(
        &mut response,
        sinomo_network::ObjectRpcResponseStreamMode::RawStreamedDaemonBody,
    );
    Ok(DfsDirectReadStreamResponse {
        response,
        reader: Some(reader),
    })
}

fn read_blob_for_direct_read_rpc_response(
    content: &LocalContentStore,
    content_hash: &str,
    expected_size_bytes: u64,
) -> Result<Option<Vec<u8>>, DfsError> {
    let mut reader = match content.open_blob_stream(content_hash) {
        Ok(reader) => reader,
        Err(_) => return Ok(None),
    };
    if reader.size_bytes() != expected_size_bytes {
        return Ok(None);
    }
    let capacity = dfs_byte_count_to_usize("DFS direct read RPC", expected_size_bytes)?;
    let mut bytes = Vec::with_capacity(capacity);
    reader
        .read_to_end(&mut bytes)
        .map_err(|source| DfsError::ContentStore {
            message: format!("failed to read blob {content_hash}: {source}"),
        })?;
    if bytes.len() != capacity {
        return Err(DfsError::ContentStore {
            message: format!(
                "failed to read full blob {content_hash}: expected {capacity} bytes, actual {}",
                bytes.len()
            ),
        });
    }
    Ok(Some(bytes))
}

fn dfs_direct_read_rpc_response(
    response: DfsReadResponse,
) -> Result<ObjectRpcResponse, NetworkError> {
    let mut rpc_response = ObjectRpcResponse::from_encoded_body(DFS_DIRECT_READ_ROUTE, Vec::new());
    rpc_response.metadata.insert(
        DFS_DIRECT_READ_REQUEST_ID_METADATA_KEY.to_string(),
        response.request_id.clone(),
    );
    rpc_response.metadata.insert(
        DFS_DIRECT_READ_OBJECT_ID_METADATA_KEY.to_string(),
        response.object_id.to_string(),
    );
    match response.result {
        DfsReadResult::Found(data) => {
            rpc_response.metadata.insert(
                DFS_DIRECT_READ_STATUS_METADATA_KEY.to_string(),
                DFS_DIRECT_READ_STATUS_FOUND.to_string(),
            );
            rpc_response.metadata.insert(
                DFS_DIRECT_READ_OBJECT_ID_METADATA_KEY.to_string(),
                data.object_id.to_string(),
            );
            rpc_response.metadata.insert(
                DFS_DIRECT_READ_VERSION_METADATA_KEY.to_string(),
                data.version.to_string(),
            );
            if let Some(content_hash) = data.content_hash {
                rpc_response.metadata.insert(
                    DFS_DIRECT_READ_CONTENT_HASH_METADATA_KEY.to_string(),
                    content_hash,
                );
            }
            rpc_response.metadata.insert(
                DFS_DIRECT_READ_CONTENT_SIZE_METADATA_KEY.to_string(),
                data.bytes.len().to_string(),
            );
            rpc_response.body = data.bytes;
        }
        DfsReadResult::NotFound => {
            rpc_response.metadata.insert(
                DFS_DIRECT_READ_STATUS_METADATA_KEY.to_string(),
                DFS_DIRECT_READ_STATUS_NOT_FOUND.to_string(),
            );
        }
        DfsReadResult::Rejected { reason } => {
            rpc_response.metadata.insert(
                DFS_DIRECT_READ_STATUS_METADATA_KEY.to_string(),
                DFS_DIRECT_READ_STATUS_REJECTED.to_string(),
            );
            rpc_response
                .metadata
                .insert(DFS_DIRECT_READ_REJECTION_METADATA_KEY.to_string(), reason);
        }
        DfsReadResult::RangeFound(_) => {
            return Err(dfs_network_serialization_error(
                "DFS direct read route cannot encode range responses",
            ));
        }
    }
    Ok(rpc_response)
}

#[cfg(test)]
pub(crate) fn dfs_message_response_from_direct_read_rpc_response(
    command: &DfsMessageCommand,
    response: ObjectRpcResponse,
) -> Result<DfsMessageResponse, NetworkError> {
    let response = dfs_direct_read_response_from_rpc_response(response)?;
    Ok(DfsMessageResponse {
        request_id: command.request_id.clone(),
        outbound_messages: vec![DfsRoutedMessage {
            source_node_id: command.routed_message.target_node_id.clone(),
            target_node_id: command.routed_message.source_node_id.clone(),
            frame_id: command.routed_message.frame_id,
            message_id: command.routed_message.message_id,
            message: DfsNetworkMessage::ReadResponse(response),
        }],
    })
}

pub fn dfs_direct_read_response_from_rpc_response(
    mut response: ObjectRpcResponse,
) -> Result<DfsReadResponse, NetworkError> {
    response.error_detail()?;
    let status = dfs_direct_read_metadata(&response, DFS_DIRECT_READ_STATUS_METADATA_KEY)?;
    let request_id =
        dfs_direct_read_metadata(&response, DFS_DIRECT_READ_REQUEST_ID_METADATA_KEY)?.to_string();
    let object_id = dfs_direct_read_metadata_id(&response, DFS_DIRECT_READ_OBJECT_ID_METADATA_KEY)?;
    let result = match status {
        DFS_DIRECT_READ_STATUS_FOUND => {
            let version =
                dfs_direct_read_metadata_id(&response, DFS_DIRECT_READ_VERSION_METADATA_KEY)?;
            let content_hash =
                dfs_direct_read_metadata(&response, DFS_DIRECT_READ_CONTENT_HASH_METADATA_KEY)?
                    .to_string();
            let content_size_bytes = dfs_direct_read_metadata_usize(
                &response,
                DFS_DIRECT_READ_CONTENT_SIZE_METADATA_KEY,
            )?;
            if response.body.len() != content_size_bytes {
                return Err(dfs_network_serialization_error(format!(
                    "DFS direct read response body has {} bytes, metadata expected {}",
                    response.body.len(),
                    content_size_bytes
                )));
            }
            DfsReadResult::Found(DfsReadData {
                object_id: object_id.clone(),
                version,
                content_hash: Some(content_hash),
                bytes: std::mem::take(&mut response.body),
            })
        }
        DFS_DIRECT_READ_STATUS_NOT_FOUND => DfsReadResult::NotFound,
        DFS_DIRECT_READ_STATUS_REJECTED => {
            let reason =
                dfs_direct_read_metadata(&response, DFS_DIRECT_READ_REJECTION_METADATA_KEY)?
                    .to_string();
            DfsReadResult::Rejected { reason }
        }
        other => {
            return Err(dfs_network_serialization_error(format!(
                "unknown DFS direct read status {other}"
            )));
        }
    };
    Ok(DfsReadResponse {
        request_id,
        object_id,
        result,
    })
}

fn dfs_direct_read_metadata<'a>(
    response: &'a ObjectRpcResponse,
    key: &str,
) -> Result<&'a str, NetworkError> {
    response
        .metadata
        .get(key)
        .map(String::as_str)
        .ok_or_else(|| {
            dfs_network_serialization_error(format!("missing DFS direct read metadata {key}"))
        })
}

fn dfs_direct_read_metadata_id(
    response: &ObjectRpcResponse,
    key: &str,
) -> Result<sinomo_core::Id, NetworkError> {
    let value = dfs_direct_read_metadata(response, key)?;
    sinomo_core::Id::new(value).map_err(|source| {
        dfs_network_serialization_error(format!("invalid DFS direct read metadata {key}: {source}"))
    })
}

fn dfs_direct_read_metadata_usize(
    response: &ObjectRpcResponse,
    key: &str,
) -> Result<usize, NetworkError> {
    let value = dfs_direct_read_metadata(response, key)?;
    value.parse::<usize>().map_err(|source| {
        dfs_network_serialization_error(format!("invalid DFS direct read metadata {key}: {source}"))
    })
}

fn dfs_network_serialization_error(detail: impl Into<String>) -> NetworkError {
    NetworkError::Serialization {
        detail: detail.into(),
    }
}

pub(crate) const DFS_BLOB_INLINE_LIMIT_BYTES: usize = 1024 * 1024;
const DFS_BLOB_CHUNK_BYTES: usize = 4 * 1024 * 1024;
const DFS_DIRECT_REMOTE_READ_MAX_BYTES: u64 = 128 * 1024 * 1024;
const DFS_STAGE_CHUNK_WINDOW_SIZE: u32 = 4;
const DFS_READ_CHUNK_WINDOW_SIZE: u32 = 4;
const DFS_FETCH_CHUNK_WINDOW_SIZE: u32 = 4;
const DFS_LAN_CHUNK_WINDOW_SIZE: u32 = 16;
const DFS_LOCAL_CHUNK_WINDOW_SIZE: u32 = 16;
const DFS_ADAPTIVE_TRANSFER_WINDOW_MAX_BYTES: u64 = 16 * 1024 * 1024;
const DFS_REMOTE_READ_RETRY_DELAY: Duration = Duration::from_secs(1);
const DFS_CHUNK_TRANSFER_IDLE_TIMEOUT: Duration = Duration::from_secs(60);
const DFS_REPAIR_RETRY_SUPPRESSED_TICK: u64 = u64::MAX;
const DFS_REPAIR_RETRY_TICK_DURATION: Duration = Duration::from_secs(5);
const DFS_METADATA_HYDRATE_OBJECT_PAGE_SIZE: usize = 4096;
const DFS_METADATA_OBJECT_VERSION_PAGE_SIZE: usize = 1024;
const DFS_METADATA_OBJECT_INTENT_PAGE_SIZE: usize = 1024;
const DFS_METADATA_OBJECT_RECEIPT_PAGE_SIZE: usize = 1024;
const DFS_ANTI_ENTROPY_DEFAULT_OBJECT_PAGE_SIZE: usize = 1024;
const DFS_ANTI_ENTROPY_DEFAULT_ISSUE_LIMIT: usize = 1024;
#[cfg(not(test))]
const DFS_CONFLICT_SCAN_PAGE_SIZE: usize = 1024;
#[cfg(test)]
const DFS_CONFLICT_SCAN_PAGE_SIZE: usize = 2;

fn dfs_adaptive_chunk_window_size(
    profile: DfsTransferProfile,
    total_size_bytes: u64,
    base_window_chunks: u32,
) -> u32 {
    let total_chunks = total_size_bytes
        .div_ceil(DFS_BLOB_CHUNK_BYTES as u64)
        .clamp(1, u64::from(u32::MAX)) as u32;
    let profile_window = match profile {
        DfsTransferProfile::Conservative => base_window_chunks,
        DfsTransferProfile::Lan => base_window_chunks.max(DFS_LAN_CHUNK_WINDOW_SIZE),
        DfsTransferProfile::Local => base_window_chunks.max(DFS_LOCAL_CHUNK_WINDOW_SIZE),
    };
    let budget_window = (DFS_ADAPTIVE_TRANSFER_WINDOW_MAX_BYTES / DFS_BLOB_CHUNK_BYTES as u64)
        .clamp(1, u64::from(u32::MAX)) as u32;
    profile_window.min(budget_window).min(total_chunks).max(1)
}

pub fn register_storage_paths(
    layout: &mut sinomo_storage::StorageLayout,
) -> Result<(), sinomo_storage::StorageContractError> {
    use sinomo_storage::StorageRing;

    for (relative_path, reason) in [
        ("dfs/content/blobs", "content-addressed DFS blob bytes"),
        (
            "dfs/content/blob-packs",
            "packed small DFS blob segment files and index records",
        ),
        (
            "dfs/content/objects",
            "dynamic DFS object manifests stored as sinomo-object files",
        ),
        (
            "dfs/content/stats.sobj",
            "durable approximate DFS content-store counters",
        ),
        (
            "dfs/content/stats.lock",
            "advisory lock for DFS content-store counter updates",
        ),
        ("dfs/content/staging", "temporary DFS staging bytes"),
        (
            "dfs/metadata/records",
            "dynamic DFS metadata records stored as sinomo-object files",
        ),
        (
            "dfs/metadata/journal",
            "dynamic DFS metadata journal entries stored as sinomo-object files",
        ),
        (
            "dfs/metadata/root",
            "default DFS root metadata shard with object records and journal entries",
        ),
        (
            "dfs/metadata/shard-index",
            "dynamic DFS object-to-metadata-shard index records",
        ),
        (
            "dfs/metadata-replication-cursors",
            "durable per-replica DFS metadata journal replication cursors",
        ),
        (
            "dfs/maintenance",
            "durable DFS maintenance cursors, retry ledgers, and suppression records",
        ),
        (
            "dfs/metadata",
            "dynamic DFS metadata shard directories with object records and journal entries",
        ),
        (
            "dfs/imports",
            "quarantined DFS metadata imported from migrated source clusters",
        ),
        (
            "dfs/operator",
            "dynamic DFS operator intent records stored as sinomo-object files",
        ),
        (
            "dfs/pins",
            "dynamic DFS pin records stored as sinomo-object files",
        ),
        ("files", "local-owned user files exposed into DFS"),
    ] {
        layout.register_escape_path("sinomo-dfs", StorageRing::R1, relative_path, reason)?;
    }
    Ok(())
}

pub fn dfs_module_id() -> sinomo_module::ModuleId {
    sinomo_module::ModuleId::from_legacy_named(SINOMO_DFS_MODULE_LEGACY_ID)
        .expect("valid DFS module id")
}

pub fn dfs_module_surfaces() -> sinomo_module::ModuleSurfaces {
    use sinomo_module::{ModuleObjectRpcRoute, ModuleRouteAuth, ModuleSurfaces};

    let mut surfaces = ModuleSurfaces::default()
        .with_object_rpc_route(ModuleObjectRpcRoute::new(
            DFS_STATUS_ROUTE,
            DFS_RPC_CATEGORY,
            "dfs.status.read",
            ModuleRouteAuth::LocalOrClusterMember,
        ))
        .with_object_rpc_route(ModuleObjectRpcRoute::new(
            DFS_EXPOSE_CONFIG_ROUTE,
            DFS_RPC_CATEGORY,
            "dfs.expose.configure",
            ModuleRouteAuth::LocalCommand,
        ))
        .with_object_rpc_route(ModuleObjectRpcRoute::new(
            DFS_INSPECTION_ROUTE,
            DFS_RPC_CATEGORY,
            "dfs.inspection.read",
            ModuleRouteAuth::LocalOrClusterMember,
        ))
        .with_object_rpc_route(ModuleObjectRpcRoute::new(
            DFS_METADATA_JOURNAL_BATCH_ROUTE,
            DFS_RPC_CATEGORY,
            "dfs.metadata.replicate",
            ModuleRouteAuth::LocalOrClusterMember,
        ))
        .with_object_rpc_route(ModuleObjectRpcRoute::new(
            DFS_METADATA_SNAPSHOT_INSTALL_ROUTE,
            DFS_RPC_CATEGORY,
            "dfs.metadata.repair",
            ModuleRouteAuth::LocalOrClusterMember,
        ))
        .with_object_rpc_route(ModuleObjectRpcRoute::new(
            DFS_SMOKE_ROUTE,
            DFS_RPC_CATEGORY,
            "dfs.smoke.run",
            ModuleRouteAuth::LocalCommand,
        ))
        .with_object_rpc_route(ModuleObjectRpcRoute::new(
            DFS_DIRECT_READ_ROUTE,
            DFS_RPC_CATEGORY,
            "dfs.object.transfer",
            ModuleRouteAuth::LocalOrClusterMember,
        ))
        .with_event_kind_name(DFS_POLICY_VIOLATION_EVENT_KIND)
        .with_storage_owner(SINOMO_DFS_MODULE_OWNER);
    for route in DFS_MESSAGE_DATA_PLANE_ROUTES.iter().copied() {
        surfaces = surfaces.with_object_rpc_route(ModuleObjectRpcRoute::new(
            route,
            DFS_RPC_CATEGORY,
            "dfs.object.transfer",
            ModuleRouteAuth::LocalOrClusterMember,
        ));
    }
    surfaces.capabilities = dfs_module_capabilities();
    surfaces
}

pub fn dfs_module_registration() -> sinomo_module::ModuleRegistration {
    let mut registration = sinomo_module::ModuleRegistration::native_rust(
        dfs_module_id(),
        env!("CARGO_PKG_VERSION"),
        SINOMO_DFS_MODULE_OWNER,
        env!("CARGO_PKG_NAME"),
        DFS_PROTOCOL,
        TrustRing::R1TrustedRuntime,
        SINOMO_DFS_NATIVE_REGISTRATION_KEY,
    );
    registration.manifest.capabilities = dfs_module_capabilities();
    registration.manifest.limits = ModuleResourceLimits {
        network: NetworkAccess::Allowlisted,
        filesystem: FileSystemAccess::Scoped,
        ..ModuleResourceLimits::default()
    };
    registration.surfaces = dfs_module_surfaces();
    registration
}

pub fn dfs_module_capabilities() -> ModuleCapabilities {
    ModuleCapabilities {
        imports: vec![
            dfs_capability("storage.local.read"),
            dfs_capability("storage.local.write"),
            dfs_capability("network.object_rpc"),
            dfs_capability("cluster.kv.read"),
        ],
        exports: vec![
            dfs_capability("dfs.status.read"),
            dfs_capability("dfs.inspection.read"),
            dfs_capability("dfs.expose.configure"),
            dfs_capability("dfs.metadata.replicate"),
            dfs_capability("dfs.metadata.repair"),
            dfs_capability("dfs.smoke.run"),
            dfs_capability("dfs.object.transfer"),
            dfs_capability("sifs.path.access"),
        ],
    }
}

fn dfs_capability(name: &str) -> CapabilityName {
    CapabilityName::new(name).expect("valid DFS module capability")
}

#[cfg(test)]
mod module_registration_tests {
    use super::*;
    use sinomo_core::ModuleKind;
    use sinomo_module::{ModuleBackendRegistration, NativeRustBackendRegistration};
    use sinomo_storage::StorageLayout;

    #[test]
    fn dfs_registers_as_r1_native_rust_module() {
        let registration = dfs_module_registration();

        assert_eq!(registration.module_id(), &dfs_module_id());
        assert_eq!(registration.manifest.kind, ModuleKind::NativeRust);
        assert_eq!(
            registration.manifest.target_ring,
            TrustRing::R1TrustedRuntime
        );
        assert_eq!(registration.manifest.api_version, DFS_PROTOCOL);
        assert!(
            registration
                .manifest
                .capabilities
                .exports
                .iter()
                .any(|capability| capability.as_str() == "dfs.metadata.replicate")
        );
        assert_eq!(
            registration.backend,
            ModuleBackendRegistration::NativeRust {
                registration: NativeRustBackendRegistration::new(
                    SINOMO_DFS_NATIVE_REGISTRATION_KEY,
                    SINOMO_DFS_MODULE_OWNER
                )
            }
        );
        assert_eq!(
            registration.surfaces.storage_owners,
            vec![SINOMO_DFS_MODULE_OWNER.to_string()]
        );
        assert!(
            registration
                .surfaces
                .event_kinds
                .iter()
                .any(|event_kind| event_kind.as_str() == DFS_POLICY_VIOLATION_EVENT_KIND)
        );
        assert!(
            registration
                .surfaces
                .capabilities
                .exports
                .iter()
                .any(|capability| capability.as_str() == "dfs.object.transfer")
        );
        assert_eq!(
            registration.surfaces.object_rpc_routes.len(),
            DFS_OBJECT_RPC_ROUTES.len()
        );
        assert!(
            registration
                .surfaces
                .object_rpc_routes
                .iter()
                .all(|route| route.route != "/dfs/message")
        );
        assert!(
            registration
                .surfaces
                .object_rpc_routes
                .iter()
                .any(|route| route.route == DFS_DATA_READ_ROUTE
                    && route.operation == "dfs.object.transfer")
        );
        assert!(
            registration
                .surfaces
                .object_rpc_routes
                .iter()
                .all(|route| route.route != "/dfs/protocol/frame")
        );
    }

    #[test]
    fn dfs_storage_contract_covers_dynamic_metadata_shards() {
        let mut layout = StorageLayout::new();
        register_storage_paths(&mut layout).expect("register DFS storage paths");

        for path in [
            "dfs/content/blob-packs/index.sobj",
            "dfs/content/blob-packs/segments/0000000000000000.pack",
            "dfs/content/stats.sobj",
            "dfs/metadata/services/records/tables/materialized.slog",
            "dfs/metadata/users/journal/segments/00000000000000000001.slog",
            "dfs/metadata/custom-shard/records/objects/example.sobj",
        ] {
            assert!(
                layout.owner_for(path).is_some(),
                "storage contract should cover {path}"
            );
        }
    }
}

