pub fn open_cluster_aware_dfs_metadata_backend(
    data_dir: &SinomoDataDir,
    cluster_paths: &ClusterPaths,
) -> Result<Box<dyn DfsMetadataBackend>, DfsError> {
    if cluster_paths.state.exists()
        && let Some(metadata) = open_cluster_sharded_dfs_metadata_backend(data_dir, cluster_paths)?
    {
        return Ok(Box::new(metadata));
    }
    open_root_local_metadata_backend(default_dfs_metadata_root(data_dir))
        .map(|backend| Box::new(backend) as Box<dyn DfsMetadataBackend>)
        .map_err(Into::into)
}

pub fn open_cluster_sharded_dfs_metadata_backend(
    data_dir: &SinomoDataDir,
    cluster_paths: &ClusterPaths,
) -> Result<Option<LocalShardedMetadataBackend>, DfsError> {
    let file_system_id = sifs_file_system_id();
    let shards = cluster_dfs_metadata_shards(cluster_paths, &file_system_id)?;
    if shards.is_empty() {
        return Ok(None);
    }
    open_local_sharded_metadata_backend(default_dfs_metadata_shards_root(data_dir), shards)
        .map(Some)
        .map_err(Into::into)
}

pub fn cluster_dfs_metadata_shards(
    cluster_paths: &ClusterPaths,
    file_system_id: &DfsFileSystemId,
) -> Result<Vec<DfsMetadataShardConfig>, DfsError> {
    let mut shards = sinomo_kv::read_cluster_kv_prefix_entries(
        &cluster_paths.kv_paths(),
        &format!("{}/", metadata_shards_prefix(file_system_id)),
    )
    .map_err(DfsError::from)?
    .into_iter()
    .map(|entry| entry.decode::<DfsMetadataShardConfig>())
    .collect::<Result<Vec<_>, _>>()?;
    shards.sort_by(|left, right| left.shard_id.cmp(&right.shard_id));
    Ok(shards)
}

pub fn inspect_cluster_aware_dfs_status(
    data_dir: &SinomoDataDir,
    cluster_paths: &ClusterPaths,
) -> Result<DfsOperatorStatus, DfsError> {
    let metadata = open_cluster_aware_dfs_metadata_backend(data_dir, cluster_paths)?;
    let mut status = DfsOperatorInspector::new(metadata.as_ref()).status()?;
    attach_cluster_aware_dfs_maintenance_observations(&mut status, data_dir)?;
    if let Ok(state) = sinomo_network::read_cluster_state_without_kv(cluster_paths) {
        for shard in &mut status.metadata_shards {
            if shard.primary_node_id.as_ref() == Some(&state.local_node_id) {
                shard.replay_cursors.clear();
            } else {
                shard.replica_lag.clear();
            }
        }
    }
    Ok(status)
}

fn attach_cluster_aware_dfs_maintenance_observations(
    status: &mut DfsOperatorStatus,
    data_dir: &SinomoDataDir,
) -> Result<(), DfsError> {
    status.repair_attempts =
        read_dfs_repair_attempt_snapshot(&default_dfs_repair_attempt_snapshot_path(data_dir))?
            .map(|snapshot| snapshot.records)
            .unwrap_or_default();
    Ok(())
}

pub fn inspect_cluster_aware_dfs(
    data_dir: &SinomoDataDir,
    cluster_paths: &ClusterPaths,
    request: DaemonDfsInspectionRequest,
) -> Result<DaemonDfsInspectionResponse, DfsError> {
    let metadata = open_cluster_aware_dfs_metadata_backend(data_dir, cluster_paths)?;
    let inspector = DfsOperatorInspector::new(metadata.as_ref());
    Ok(match request {
        DaemonDfsInspectionRequest::Status => {
            let mut status = inspector.status()?;
            attach_cluster_aware_dfs_maintenance_observations(&mut status, data_dir)?;
            DaemonDfsInspectionResponse::Status { status }
        }
        DaemonDfsInspectionRequest::FileSystem { file_system_id } => {
            DaemonDfsInspectionResponse::FileSystem {
                file_system: inspector.file_system(&file_system_id)?,
            }
        }
        DaemonDfsInspectionRequest::Path {
            file_system_id,
            path,
        } => DaemonDfsInspectionResponse::Path {
            object: inspector.object_by_path(&file_system_id, &path)?,
        },
        DaemonDfsInspectionRequest::Object { object_id } => DaemonDfsInspectionResponse::Object {
            object: inspector.object(&object_id)?,
        },
        DaemonDfsInspectionRequest::Conflicts {
            file_system_id,
            object_id,
            limit,
            cursor,
        } => {
            let page = inspector.conflicts_page(
                file_system_id.as_ref(),
                object_id.as_ref(),
                limit,
                cursor.as_ref(),
            )?;
            DaemonDfsInspectionResponse::Conflicts {
                conflicts: page.conflicts,
                next_cursor: page.next_cursor,
            }
        }
        DaemonDfsInspectionRequest::Repair {
            file_system_id,
            object_id,
            limit,
            cursor,
        } => {
            let page = inspector.repairs_page(
                file_system_id.as_ref(),
                object_id.as_ref(),
                limit,
                cursor.as_ref(),
            )?;
            DaemonDfsInspectionResponse::Repair {
                repairs: page.repairs,
                next_cursor: page.next_cursor,
            }
        }
    })
}

pub fn publish_cluster_dfs_metadata_journal(
    data_dir: &SinomoDataDir,
    cluster_paths: &ClusterPaths,
    sender: DfsMetadataJournalBatchSender,
    snapshot_sender: DfsMetadataSnapshotInstallSender,
    options: DfsMetadataJournalReplicationOptions,
) -> Result<DfsMetadataJournalReplicationReport, DfsError> {
    if !cluster_paths.state.exists() {
        return Ok(DfsMetadataJournalReplicationReport {
            outcomes: Vec::new(),
        });
    }

    let state = sinomo_network::read_cluster_state_without_kv(cluster_paths)
        .map_err(DfsError::from_network)?;
    let file_system = distributed_sifs(state.local_node_id.clone());
    let shards = cluster_dfs_metadata_shards(cluster_paths, &file_system.file_system_id)?;

    let endpoints = cluster_dfs_data_endpoints(cluster_paths, &state);
    let mut transport = DfsMetadataEndpointTransport::new(endpoints, sender, snapshot_sender);
    let mut host = LocalDfsMetadataJournalPublisherHost::new(data_dir.clone());
    publish_dfs_metadata_journal_with_host(
        file_system.file_system_id,
        &state.local_node_id,
        shards,
        &mut host,
        &mut transport,
        options,
    )
}

pub async fn publish_cluster_dfs_metadata_journal_async(
    data_dir: &SinomoDataDir,
    cluster_paths: &ClusterPaths,
    sender: AsyncDfsMetadataJournalBatchSender,
    snapshot_sender: AsyncDfsMetadataSnapshotInstallSender,
    options: DfsMetadataJournalReplicationOptions,
) -> Result<DfsMetadataJournalReplicationReport, DfsError> {
    let Some(plan) =
        prepare_cluster_dfs_metadata_journal_publish_async(data_dir, cluster_paths, options)
            .await?
    else {
        return Ok(DfsMetadataJournalReplicationReport {
            outcomes: Vec::new(),
        });
    };
    let mut transport =
        AsyncDfsMetadataEndpointTransport::new(plan.endpoints.clone(), sender, snapshot_sender);
    execute_prepared_dfs_metadata_journal_publish_async(plan, &mut transport, options).await
}

pub fn publish_cluster_dfs_metadata_journal_with_peer_transport(
    data_dir: &SinomoDataDir,
    cluster_paths: &ClusterPaths,
    peer_transport: Arc<dyn DfsPeerTransport>,
    options: DfsMetadataJournalReplicationOptions,
) -> Result<DfsMetadataJournalReplicationReport, DfsError> {
    refresh_cluster_dfs_kv_snapshot_before_metadata_publish_with_peer_transport(
        cluster_paths,
        peer_transport.as_ref(),
    )?;
    publish_cluster_dfs_metadata_journal(
        data_dir,
        cluster_paths,
        dfs_metadata_journal_batch_sender_from_peer_transport(Arc::clone(&peer_transport)),
        dfs_metadata_snapshot_install_sender_from_peer_transport(peer_transport),
        options,
    )
}

pub async fn publish_cluster_dfs_metadata_journal_with_async_peer_transport(
    data_dir: &SinomoDataDir,
    cluster_paths: &ClusterPaths,
    peer_transport: Arc<dyn AsyncDfsPeerTransport>,
    options: DfsMetadataJournalReplicationOptions,
) -> Result<DfsMetadataJournalReplicationReport, DfsError> {
    publish_cluster_dfs_metadata_journal_async(
        data_dir,
        cluster_paths,
        async_dfs_metadata_journal_batch_sender_from_peer_transport(Arc::clone(&peer_transport)),
        async_dfs_metadata_snapshot_install_sender_from_peer_transport(peer_transport),
        options,
    )
    .await
}

pub async fn publish_cluster_dfs_metadata_journal_with_peer_transports_async(
    data_dir: &SinomoDataDir,
    cluster_paths: &ClusterPaths,
    sync_peer_transport: Arc<dyn DfsPeerTransport>,
    peer_transport: Arc<dyn AsyncDfsPeerTransport>,
    options: DfsMetadataJournalReplicationOptions,
) -> Result<DfsMetadataJournalReplicationReport, DfsError> {
    let refresh_cluster_paths = cluster_paths.clone();
    tokio::task::spawn_blocking(move || {
        refresh_cluster_dfs_kv_snapshot_before_metadata_publish_with_peer_transport(
            &refresh_cluster_paths,
            sync_peer_transport.as_ref(),
        )
    })
    .await
    .map_err(|source| DfsError::Metadata {
        message: format!("DFS metadata publish KV refresh task failed: {source}"),
    })??;

    publish_cluster_dfs_metadata_journal_async(
        data_dir,
        cluster_paths,
        async_dfs_metadata_journal_batch_sender_from_peer_transport(Arc::clone(&peer_transport)),
        async_dfs_metadata_snapshot_install_sender_from_peer_transport(peer_transport),
        options,
    )
    .await
}

pub fn refresh_cluster_dfs_kv_snapshot_with_peer_transport(
    cluster_paths: &ClusterPaths,
    peer_transport: Arc<dyn DfsPeerTransport>,
) -> Result<(), DfsError> {
    if !cluster_paths.state.exists() {
        return Ok(());
    }
    let state = sinomo_network::read_cluster_state_without_kv(cluster_paths)
        .map_err(DfsError::from_network)?;
    if sinomo_kv::cluster_kv_raft_local_is_voter(&state) {
        return Ok(());
    }
    refresh_cluster_dfs_kv_snapshot_with_peer_transport_for_state(
        cluster_paths,
        &state,
        peer_transport.as_ref(),
    )
}

fn refresh_cluster_dfs_kv_snapshot_before_metadata_publish_with_peer_transport(
    cluster_paths: &ClusterPaths,
    peer_transport: &dyn DfsPeerTransport,
) -> Result<(), DfsError> {
    if !cluster_paths.state.exists() {
        return Ok(());
    }
    let state = sinomo_network::read_cluster_state_without_kv(cluster_paths)
        .map_err(DfsError::from_network)?;
    if sinomo_kv::cluster_kv_raft_local_is_voter(&state) {
        return Ok(());
    }
    let file_system = distributed_sifs(state.local_node_id.clone());
    let shards = cluster_dfs_metadata_shards(cluster_paths, &file_system.file_system_id)?;
    if !shards
        .iter()
        .any(|shard| shard.primary_node_id == state.local_node_id)
    {
        return Ok(());
    }
    refresh_cluster_dfs_kv_snapshot_with_peer_transport_for_state(
        cluster_paths,
        &state,
        peer_transport,
    )
}

fn refresh_cluster_dfs_kv_snapshot_with_peer_transport_for_state(
    cluster_paths: &ClusterPaths,
    state: &ClusterBootstrapState,
    peer_transport: &dyn DfsPeerTransport,
) -> Result<(), DfsError> {
    let payload = sinomo_kv::cluster_kv_snapshot_rpc_payload()?;
    let request = object_rpc_request_from_kv_payload(payload);
    let options = sinomo_network::ClusterControlPlaneTimeouts::default_daemon_transport()
        .kv_snapshot_refresh_options();
    let _ = sinomo_network::refresh_current_cluster_kv_store_with_local_storage_and_transport(
        cluster_paths,
        state,
        options,
        |endpoint, timeout| {
            let response = peer_transport
                .call_object_rpc(
                    &endpoint.node_id,
                    &request,
                    DfsObjectRpcSendOptions::new(timeout).with_observe_connectivity(false),
                )
                .map_err(|source| NetworkError::Io {
                    operation: "DFS cluster KV snapshot refresh".to_string(),
                    detail: source.to_string(),
                })?;
            response.error_detail()?;
            sinomo_kv::decode_cluster_kv_snapshot_rpc_body(&response.body).map_err(Into::into)
        },
    );
    Ok(())
}

